import type { HTMLAttributes, ReactElement, ReactNode, Ref } from "react";
import { Children, cloneElement, isValidElement } from "react";
import type { AvatarProps } from "../avatar/avatar";
import { cx, sortCx } from "@/lib/utils";

/**
 * Stacked avatars for teammates / assignees — ringed like notification
 * badges on JoyUI sidebar surfaces.
 *
 *   <AvatarGroup max={3}>
 *     <Avatar initials="A" />
 *     <Avatar initials="B" />
 *     <Avatar initials="C" />
 *     <Avatar initials="D" />
 *   </AvatarGroup>
 */

export type AvatarGroupSize = NonNullable<AvatarProps["size"]>;

export interface AvatarGroupProps extends HTMLAttributes<HTMLDivElement> {
  children?: ReactNode;
  /** How many faces to show before +N. Default 3. */
  max?: number;
  size?: AvatarGroupSize;
  ref?: Ref<HTMLDivElement>;
}

const ring = sortCx({
  base: "relative inline-flex items-center",
  size: {
    xs: "-space-x-1.5",
    sm: "-space-x-2",
    md: "-space-x-2.5",
    lg: "-space-x-3",
  },
});

const face = sortCx({
  base: "relative ring-2 ring-background-primary-default",
});

const overflow = sortCx({
  // Soft chip on tertiary — matches Chip `soft` / avatar neutral fallback.
  base: "relative z-10 inline-flex shrink-0 items-center justify-center rounded-full bg-background-tertiary-default text-text-secondary ring-2 ring-background-primary-default",
  size: {
    xs: "size-5 text-[9px] font-semibold leading-none",
    sm: "size-6 text-caption-1-semibold",
    md: "size-8 text-caption-1-semibold",
    lg: "size-9 text-headline-semibold",
  },
});

export function AvatarGroup({
  children,
  max = 3,
  size = "md",
  className,
  ref,
  ...props
}: AvatarGroupProps) {
  const items = Children.toArray(children).filter(isValidElement) as ReactElement<AvatarProps>[];
  const visible = items.slice(0, Math.max(0, max));
  const rest = Math.max(0, items.length - visible.length);

  return (
    <div
      ref={ref}
      role="group"
      className={cx(ring.base, ring.size[size], className)}
      {...props}
    >
      {visible.map((child, i) =>
        cloneElement(child, {
          size: child.props.size ?? size,
          className: cx(face.base, child.props.className),
          style: { zIndex: visible.length - i, ...child.props.style },
        }),
      )}
      {rest > 0 ? (
        <span className={cx(overflow.base, overflow.size[size])} style={{ zIndex: 0 }}>
          +{rest}
        </span>
      ) : null}
    </div>
  );
}
